static uint8_t dndolphins_spell_combat_saturating_dice_count(uint16_t value) {
    return value > 80U ? 80U : (uint8_t)value;
}

static size_t dndolphins_spell_combat_bounded_strlen(const char* text, size_t capacity) {
    if(!text) return 0U;
    size_t length = 0U;
    while(length < capacity && text[length])
        ++length;
    return length;
}

static uint8_t dndolphins_spell_combat_cantrip_multiplier(uint8_t character_level) {
    if(character_level >= 17U) return 4U;
    if(character_level >= 11U) return 3U;
    if(character_level >= 5U) return 2U;
    return 1U;
}

static bool dndolphins_spell_combat_contains_ci(const char* text, const char* needle) {
    if(!text || !needle || !*needle) return false;
    size_t text_len = dndolphins_spell_combat_bounded_strlen(text, DND_DETAIL_LEN);
    size_t needle_len = strlen(needle);
    if(!needle_len || needle_len > text_len) return false;
    for(size_t cursor = 0U; cursor + needle_len <= text_len; ++cursor) {
        size_t index = 0U;
        while(index < needle_len && tolower((unsigned char)text[cursor + index]) ==
                                        tolower((unsigned char)needle[index]))
            ++index;
        if(index == needle_len) return true;
    }
    return false;
}

static bool dndolphins_spell_combat_parse_damage_dice(
    const char* text,
    uint8_t* dice,
    uint8_t* die,
    int16_t* flat_bonus) {
    if(!text || !dice || !die || !flat_bonus) return false;
    size_t text_len = dndolphins_spell_combat_bounded_strlen(text, DND_DETAIL_LEN);
    for(size_t cursor_index = 0U; cursor_index < text_len; ++cursor_index) {
        const char* cursor = text + cursor_index;
        if(!isdigit((unsigned char)*cursor)) continue;
        if(cursor_index && isdigit((unsigned char)cursor[-1])) continue;

        uint16_t count = 0U;
        const char* position = cursor;
        const char* limit = text + text_len;
        while(position < limit && isdigit((unsigned char)*position)) {
            uint8_t digit = (uint8_t)(*position - '0');
            if(count > 80U / 10U || (count == 80U / 10U && digit > 80U % 10U)) {
                count = 0U;
                break;
            }
            count = (uint16_t)(count * 10U + digit);
            ++position;
        }
        while(position < limit && isspace((unsigned char)*position))
            ++position;
        if(count < 1U || position >= limit || (*position != 'd' && *position != 'D')) continue;
        ++position;
        while(position < limit && isspace((unsigned char)*position))
            ++position;
        if(position >= limit || !isdigit((unsigned char)*position)) continue;

        uint16_t sides = 0U;
        while(position < limit && isdigit((unsigned char)*position)) {
            uint8_t digit = (uint8_t)(*position - '0');
            if(sides > 100U / 10U || (sides == 100U / 10U && digit > 100U % 10U)) {
                sides = 0U;
                break;
            }
            sides = (uint16_t)(sides * 10U + digit);
            ++position;
        }
        if(sides < 2U) continue;

        int16_t bonus = 0;
        while(position < limit && isspace((unsigned char)*position))
            ++position;
        if(position < limit && (*position == '+' || *position == '-')) {
            int sign = *position++ == '-' ? -1 : 1;
            while(position < limit && isspace((unsigned char)*position))
                ++position;
            if(position < limit && isdigit((unsigned char)*position)) {
                uint16_t value = 0U;
                while(position < limit && isdigit((unsigned char)*position)) {
                    uint8_t digit = (uint8_t)(*position - '0');
                    if(value > 999U / 10U || (value == 999U / 10U && digit > 999U % 10U)) {
                        value = 999U;
                        while(position < limit && isdigit((unsigned char)*position))
                            ++position;
                        break;
                    }
                    value = (uint16_t)(value * 10U + digit);
                    ++position;
                }
                bonus = (int16_t)(sign * (int)value);
            }
        }

        *dice = (uint8_t)count;
        *die = (uint8_t)sides;
        *flat_bonus = bonus;
        return true;
    }
    return false;
}

bool dndolphins_spell_combat_damage_spec(
    const DndSpell* spell,
    uint8_t cast_level,
    uint8_t character_level,
    int8_t spellcasting_modifier,
    DndSpellDamageSpec* output) {
    if(!spell || !output) return false;
    memset(output, 0, sizeof(*output));

    for(size_t index = 0U; index < sizeof(dndolphins_spell_combat_damage_map) /
                                       sizeof(dndolphins_spell_combat_damage_map[0]);
        ++index) {
        const DndSpellDamageMap* mapped = &dndolphins_spell_combat_damage_map[index];
        if(strncmp(mapped->name, spell->name, DND_SPELL_NAME_LEN) != 0) continue;
        uint8_t multiplier = mapped->cantrip_scale ?
                                 dndolphins_spell_combat_cantrip_multiplier(character_level) :
                                 1U;
        uint8_t safe_cast_level = cast_level < DND_SLOT_COUNT ? cast_level : 9U;
        uint8_t safe_spell_level = spell->level < DND_SLOT_COUNT ? spell->level : 9U;
        uint8_t upcast = safe_cast_level > safe_spell_level ?
                             (uint8_t)(safe_cast_level - safe_spell_level) :
                             0U;
        output->primary_dice = dndolphins_spell_combat_saturating_dice_count(
            (uint16_t)mapped->primary_dice * multiplier +
            (uint16_t)mapped->primary_upcast * upcast);
        output->primary_die = mapped->primary_die;
        output->secondary_dice = dndolphins_spell_combat_saturating_dice_count(
            (uint16_t)mapped->secondary_dice * multiplier +
            (uint16_t)mapped->secondary_upcast * upcast);
        output->secondary_die = mapped->secondary_die;
        output->flat_bonus = (int16_t)mapped->flat_bonus + (int16_t)mapped->flat_upcast * upcast;
        output->secondary_flat_bonus = (int16_t)mapped->secondary_flat_bonus +
                                       (int16_t)mapped->secondary_flat_upcast * upcast;
        if(mapped->add_spellcasting_modifier) output->flat_bonus += spellcasting_modifier;
        if(mapped->add_secondary_spellcasting_modifier)
            output->secondary_flat_bonus += spellcasting_modifier;
        output->resolution = mapped->resolution;
        output->secondary_resolution = mapped->secondary_resolution;
        output->secondary_relation = mapped->secondary_relation;
        output->derived_effect = mapped->derived_effect;
        output->special = strncmp(spell->name, "Sorcerous Burst", DND_SPELL_NAME_LEN) == 0 ?
                              DndSpellSpecialSorcerousBurst :
                              DndSpellSpecialNone;
        if(mapped->cantrip_attack_scale)
            output->attack_rolls = dndolphins_spell_combat_cantrip_multiplier(character_level);
        else {
            uint16_t attacks =
                (uint16_t)mapped->attack_rolls + (uint16_t)mapped->attack_rolls_upcast * upcast;
            output->attack_rolls = attacks > 12U ? 12U : (uint8_t)attacks;
        }
        uint16_t instances =
            (uint16_t)mapped->roll_instances + (uint16_t)mapped->roll_instances_upcast * upcast;
        output->roll_instances = instances > 12U ? 12U : (uint8_t)instances;
        if(output->resolution == DndSpellResolutionAttack && !output->attack_rolls)
            output->attack_rolls = 1U;
        return true;
    }

    if(dndolphins_spell_combat_parse_damage_dice(
           spell->detail, &output->primary_dice, &output->primary_die, &output->flat_bonus)) {
        /* A plain XdY note is treated as spell-attack damage. Authors can include
         * "save" or "DC" in the note to make the fallback use the spell save DC instead. */
        output->resolution = (dndolphins_spell_combat_contains_ci(spell->detail, "save") ||
                              dndolphins_spell_combat_contains_ci(spell->detail, "dc")) ?
                                 DndSpellResolutionSave :
                                 DndSpellResolutionAttack;
        output->attack_rolls = output->resolution == DndSpellResolutionAttack ? 1U : 0U;
        output->from_notes = 1U;
        return true;
    }
    return false;
}
